<style>
.container{width:min(1180px,92%);margin-inline:auto}.content-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:22px;margin:28px 0}.content-card{background:#fff;border:1px solid #e4edf1;border-radius:14px;overflow:hidden;box-shadow:0 8px 24px rgba(10,48,70,.05);transition:transform .25s,box-shadow .25s}.content-card:hover{transform:translateY(-5px);box-shadow:0 16px 35px rgba(10,48,70,.12)}.content-card>img{width:100%;height:190px;object-fit:cover}.content-card-body{padding:18px}.content-card h2,.content-card h3{font-size:19px;margin:0 0 8px}.content-card a{color:#103b56;text-decoration:none}.content-card a:hover{color:#0799a5}.content-card p{color:#637987;line-height:1.6}.eyebrow{color:#0799a5;text-transform:uppercase;letter-spacing:2px;font-size:11px;font-weight:700}@media(max-width:800px){.content-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:560px){.content-grid{grid-template-columns:1fr}}
</style>
